enum Role {Body,Glass,Metal,Interior,Wheels,Ignore};
inline const char* roleName(int r){static const char* names[]={"Painted body","Glass","Metal / chrome","Interior / plastic","Wheels (split into four)","Ignore"};return names[r];}
struct Part {std::string name,material;int role=Body;std::vector<P> positions,normals;std::vector<std::array<float,2>> uv;std::vector<uint32_t> indices;};
struct Source {std::vector<Part> parts;std::string hash;size_t triangles=0,textures=0;Bounds bounds;};
