struct Options {double scale=1;int yaw=0;bool zUp=false,fit=true;};
inline P orient(P p,const Options&o){if(o.zUp)p={p[0],p[2],-p[1]};int q=(o.yaw%4+4)%4;while(q--)p={p[2],p[1],-p[0]};for(auto&v:p)v*=o.scale;return p;}
